/* Alles hieronder hoort bij de data en wordt door meerdere pagina's gebruikt. */

/* De bandbreedte voor een model en een reparatie: laagste, mediaan en hoogste
   gemeten prijs. Geeft null als wij niets hebben gemeten; dan hoort de pagina de
   lege staat te tonen en geen getal te verzinnen. */
function bandVan(model, rep) {
  const m = KIEZERDATA.modellen.find(x => x.n === model);
  const d = m && m.data[rep];
  return d && d.alles ? [d.alles.laagste, d.alles.mediaan, d.alles.hoogste] : null;
}

/* De modelcode zoals hij onder een toestel hoort te staan. Niet elk model heeft
   er een: van de iPhone 17 weten wij hem niet en wij verzinnen hem niet. Een
   ontbrekende code liet de kiezer omvallen op m.c.split(), dus dat gaat hier. */
const modelcode = m => (m.c || '').split(' ')[0];
const codeLabel = m => modelcode(m) || 'code onbekend';

/* Waarop het zoekveld matcht: de naam, het merk en ALLE modelcodes. Alleen op
   de getoonde code zoeken is niet genoeg: iemand met een toestel dat in de
   Verenigde Staten of Japan is gekocht, leest een ander nummer van zijn scherm
   dan wij tonen, en die moet zijn toestel ook kunnen vinden. */
const zoekbaar = m =>
  ((m.n || '') + ' ' + (m.cs || [m.c]).filter(Boolean).join(' ') + ' ' + (m.merk || '')).toLowerCase();

/* Welke reparaties zijn er voor dit model gemeten? */
const repsVoor = model => {
  const m = KIEZERDATA.modellen.find(x => x.n === model);
  return m ? Object.keys(m.data) : [];
};

/* Waarop een band berust: aantal metingen, aantal winkels, en of dat er genoeg
   zijn. De plaatspagina zette onder elke band "over 198 prijspunten", het totaal
   van de hele site, ook als er voor dat model twee metingen waren. */
function metingVan(model, rep) {
  const m = KIEZERDATA.modellen.find(x => x.n === model);
  const d = m && m.data[rep];
  return d ? {metingen: d.metingen, winkels: d.winkels, genoeg: d.genoeg} : null;
}

/* Een zin onder een prijs die zegt waar hij op berust. Bij te weinig winkels
   zeggen wij dat erbij; besluit T4 zegt dat wij pas vanaf drie winkels vergelijken. */
function bronZin(model, rep) {
  const b = bandVan(model, rep), t = metingVan(model, rep);
  if (!b || !t) return 'Voor dit model hebben wij deze reparatie nog niet gemeten.';
  const geld = n => '&euro;&nbsp;' + n;
  const basis = 'Gemeten bij ' + t.winkels + (t.winkels === 1 ? ' winkel' : ' winkels') +
    ', ' + t.metingen + (t.metingen === 1 ? ' prijs' : ' prijzen') +
    ': ' + geld(b[0]) + ' tot ' + geld(b[2]) + ' (' + KIEZERDATA.peildatumTekst + ').';
  return t.genoeg ? basis
    : basis + ' Dat zijn er te weinig om een betrouwbaar beeld te geven.';
}

/* Heeft deze reparatie kwaliteitsklassen? Bij een accu of een laadpoort zegt
   "Service pack" niets; dat label hoort bij schermen. */
const heeftKwaliteit = rep => rep === 'scherm' || rep === 'achterkant';

/* De prijs van een winkel: waar die winkel in de gemeten band zit. w.niv is het
   prijsniveau van de winkel, tussen 0 en 1. Zo blijft elke getoonde prijs binnen
   wat wij werkelijk hebben gemeten. */
function prijsVanWinkel(w, model, rep) {
  const b = bandVan(model, rep);
  if (!b) return null;
  const [lo, , hi] = b;
  return Math.max(lo, Math.round((lo + (hi - lo) * w.niv) / 5) * 5 - 1);
}
